import assert from 'node:assert/strict'
import test from 'node:test'
import { mkdir, mkdtemp, rm } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'

import { SAVE_DIR, createSave, save } from '../engine/state.js'

/**
 * The local API imports `index.js`, which pulls the dsh packages. Under
 * `--jitless` those packages lazily reach for WebAssembly after the test has
 * ended, and node:test reports that as an unhandled rejection. The server
 * itself has no WASM path and is exercised on the device (jitless) by the app,
 * so this suite runs in the normal JIT job and skips under --jitless.
 */
const jitless = process.execArgv.includes('--jitless') ||
  (process.env.NODE_OPTIONS ?? '').includes('--jitless')

test('local board API', { skip: jitless ? 'covered on-device under jitless' : false }, async () => {
  const home = await mkdtemp(join(tmpdir(), 'sanguo-local-api-'))
  const workspace = join(home, 'workspace')
  await mkdir(join(workspace, SAVE_DIR), { recursive: true })
  await save(workspace, createSave('api-test'))

  process.env.HOME = home
  process.env.DSH_SANGUO_PORT = '0'

  const { request } = await import('node:http')
  const { startLocalApi } = await import('../index.js')
  const server = startLocalApi()
  await new Promise((resolve) => server.once('listening', resolve))
  const base = `http://127.0.0.1:${server.address().port}`

  function call(method, path, body) {
    return new Promise((resolve, reject) => {
      const payload = body === undefined ? '' : JSON.stringify(body)
      const req = request(`${base}${path}`, {
        method,
        // One request, one socket: keep-alive sockets would outlive the test.
        agent: false,
        headers: body === undefined
          ? { connection: 'close' }
          : { connection: 'close', 'content-type': 'application/json', 'content-length': Buffer.byteLength(payload) }
      }, (response) => {
        const chunks = []
        response.on('data', (chunk) => chunks.push(chunk))
        response.on('end', () => {
          try {
            resolve({ status: response.statusCode, json: JSON.parse(Buffer.concat(chunks).toString('utf8')) })
          } catch (error) {
            reject(error)
          }
        })
      })
      req.on('error', reject)
      req.end(payload)
    })
  }

  try {
    const health = await call('GET', '/health')
    assert.equal(health.status, 200)
    assert.equal(health.json.ok, true)

    const state = await call('POST', '/state', { workspace })
    assert.equal(state.status, 200)
    assert.equal(state.json.ok, true)
    assert.match(state.json.rendered, /刘备/)
    assert.ok(state.json.scene)

    const act = await call('POST', '/act', {
      workspace,
      attribute: 'mei',
      difficulty: 40,
      intent: 'local api test'
    })
    assert.equal(act.status, 200)
    assert.equal(act.json.ok, true)
    assert.match(act.json.rendered, /【判定】/)
    assert.match(act.json.rendered, /【变化】/)

    const advance = await call('POST', '/advance', { workspace, turns: 1 })
    assert.equal(advance.status, 200)
    assert.equal(advance.json.ok, true)
    assert.match(advance.json.rendered, /【时间】/)

    const outside = await call('POST', '/state', { workspace: '/etc' })
    assert.equal(outside.status, 400)
    assert.equal(outside.json.ok, false)
    assert.match(outside.json.error, /workspace must be under/)
  } finally {
    server.closeAllConnections?.()
    await new Promise((resolve) => server.close(resolve))
    await rm(home, { recursive: true, force: true })
  }
})
